loginUrl:
/* 新天禧小说 · 搜搜书账号登录面板
 * ────────────────────────────────────────────────
 * ⚠️ Legado 登录协议（源码级）：
 *   1) loginUrl 里必须有名为 `login` 的函数，否则点登录抛
 *      "Function login not implements!!!"。
 *   2) 按钮 action 执行时 `java` 被替换为 SourceLoginJsExtensions，
 *      `source` 仍绑定；LT 有 longToast，E 版可能只有 toast
 *      ⇒ 本文件所有提示/请求都走 T()/AJAX() 兜底包装。
 *   3) loginUi 用 V1 静态 JSON 数组（E 版唯一可用形态）。
 * 业务背景：站点自身 /search 已被管理员关闭，搜索必须走 sososhu.com
 *   聚合站，且聚合站要求登录（每账号 12 次/天，0 点重置）。
 *   验证码由用户手动看图填写（不做自动识别，同 38看书 方案）。
 */

function SOS_BASE() { return 'https://www.sososhu.com'; }

/* 提示：LT 有 longToast，E 版回退 toast */
function T(msg) {
    try { java.longToast(String(msg)); return; } catch (e) { }
    try { java.toast(String(msg)); } catch (e2) { }
}

/* 请求兜底：ajax → connect */
function AJAX(url, optJson) {
    var full = optJson ? (url + ',' + optJson) : url;
    try { return String(java.ajax(full)); } catch (e) { }
    try { return String(java.connect(full).body()); } catch (e2) { }
    return '';
}

/* 去掉 JSON 前的 UTF-8 BOM */
function noBom(s) { return String(s || '').replace(/^\uFEFF/, ''); }

/* 刷新验证码：内置浏览器打开图片，用户看图后手填 4 位字符 */
function refreshCaptcha() {
    try {
        T('正在打开验证码，看图后把 4 位字符填到「验证码」框');
        var u = SOS_BASE() + '/?action=captcha_api&t=' + Math.random();
        try { java.startBrowser(u, '验证码'); }
        catch (e) { java.open(u); }
    } catch (e) {
        T('打开验证码失败：' + e);
    }
}

/* 登录：内置登录按钮调用 login()；自定义按钮调用 login(true)
 * 无参调用直接 return true，避免被自动触发 */
function login(b) {
    if (b == undefined) return true;
    var info = result || {};
    var mobile = String(info['手机号'] || '').replace(/\s/g, '');
    var password = String(info['密码'] || '').replace(/\s/g, '');
    var captcha = String(info['验证码'] || '').replace(/\s/g, '');

    if (!mobile || !password) { T('请填写手机号和密码'); return; }
    if (!captcha) { T('请先点「🔄刷新验证码」，看图后把 4 位字符填入'); return; }

    try {
        T('正在登录…');
        var body = 'mobile=' + encodeURIComponent(mobile)
                 + '&password=' + encodeURIComponent(password)
                 + '&captcha=' + encodeURIComponent(captcha);
        var opt = JSON.stringify({
            method: 'POST',
            body: body,
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
                'X-Requested-With': 'XMLHttpRequest',
                'Referer': SOS_BASE() + '/?action=login'
            }
        });
        var raw = noBom(AJAX(SOS_BASE() + '/?action=user_api&act=login', opt));
        var json = JSON.parse(raw);
        if (json.code === 0) {
            var name = (json.data && (json.data.name || json.data.username)) || '';
            T('✅ 登录成功：' + name);
            quota();
        } else {
            T('❌ 登录失败：' + (json.msg || '未知错误') + '（验证码错误请刷新重试）');
        }
    } catch (e) {
        T('登录异常：' + e);
    }
}

function logout() {
    try { source.removeLoginHeader(); } catch (e) { }
    try { cookie.removeCookie(SOS_BASE() + '/'); } catch (e2) { }
    T('已登出，可重新登录');
}

/* 查询今日剩余搜索次数（profile 接口不消耗额度） */
function quota() {
    try {
        var json = JSON.parse(noBom(AJAX(SOS_BASE() + '/?action=user_api&act=profile')));
        if (json.code === 0 && json.data) {
            var d = json.data;
            T('今日剩余搜索 ' + d.searchRemaining + '/' + d.searchMax + ' 次'
                + (d.signedToday ? '（今日已签到）' : '（未签到）'));
        } else {
            T('未登录或会话已过期');
        }
    } catch (e) { T('查询失败：' + e); }
}

/* 签到：只加经验，不增加搜索次数 */
function checkin() {
    try {
        var opt = JSON.stringify({ method: 'POST', headers: { 'X-Requested-With': 'XMLHttpRequest' } });
        var json = JSON.parse(noBom(AJAX(SOS_BASE() + '/?action=user_api&act=sign_in', opt)));
        if (json.code === 0) {
            T('✅ 签到成功：' + (json.msg || '') + (json.data ? '，连续' + json.data.streak + '天' : ''));
        } else {
            T('❌ 签到失败：' + (json.msg || ''));
        }
    } catch (e) { T('签到异常：' + e); }
}

/* 检查登录状态 */
function checkLogin() {
    try {
        var json = JSON.parse(noBom(AJAX(SOS_BASE() + '/?action=user_api&act=me')));
        if (json.code === 0 && json.data) {
            T('✅ 已登录：' + (json.data.name || json.data.username || ''));
            quota();
        } else {
            T('❌ 未登录，请输入账号密码、刷新验证码后点登录');
        }
    } catch (e) { T('检查失败：' + e); }
}

