(function(){
  try {
    var r = java.ajax('https://www.sososhu.com/?action=user_api&act=me');
    var j = JSON.parse(String(r).replace(/^\uFEFF/, ''));
    if (!(j && j.code === 0 && j.data)) {
      java.longToast('⚠️ 搜搜书账号未登录：搜索会失败，请到登录面板登录');
    }
  } catch (e) { }
  return result;
})();
